"""GATE's compute split (E7) and the GATE -> AIFM training-compute pass (issue #35). Stdlib only, no network.

    python3 research_notes/external/epoch-gate/coupling_example.py          # print the identities and the pass
    python3 research_notes/external/epoch-gate/coupling_example.py --write  # rewrite coupling_example.json
    python3 research_notes/external/epoch-gate/coupling_example.py --check  # fail if coupling_example.json is stale

Reads only data/baseline_target.json (the pinned solver output of #13). Two identities are checked on every run that
reports the compute split, for every pair of consecutive reported steps:

    training_compute[t] + runtime_compute[t] = g(Q[t-1]) = Q[t-1] / (Q[t-1] / C_L + 1)   (t >= 1)
    training_compute[0] + runtime_compute[0] = training_compute_init + runtime_compute_init   (step 0, uncapped)
    physical_best_training_run[t] = physical_best_training_run[t-1] + training_compute[t]

So D and R are the training and runtime shares of usable capacity at the start of the step, in physical FLOP/year.
The pass is the coupling XC-GATE-AIFM-TRAINING of systems/modes.yaml: AIFM's frontier training capacity in
H100-equivalents = s * D / 1.262e22, with s (the frontier project's share of world training compute) unidentified;
s = 1 is an upper bound only. Presets conservative and aggressive bracket GATE's own software-efficiency and
capability loops, which stay live inside D (a scenario range, not a bound). AIFM is not rerun here.
"""
import argparse
import json
from pathlib import Path
import sys

HERE = Path(__file__).resolve().parent
TARGET = HERE / 'data' / 'baseline_target.json'
OUT = HERE / 'coupling_example.json'
FLOP_PER_H100E_YEAR = 1.262e22  # AIFM's own constant (systems/modes.yaml AD-AIFM, frontier training capacity)
PRESETS = ('conservative', 'default', 'aggressive')
REPORT_STEPS = (0, 5, 10, 20)


def usable(q, c_l):
    """Usable compute g(Q) = Q / (Q / C_L + 1) (paper E19)."""
    return q / (q / c_l + 1)


def split_identities(job):
    """Largest relative errors of the two identities over consecutive reported steps, and the pairs checked."""
    t, steps, main = job['trajectory'], job['steps'], job['args']['modelParams']['main']
    c_l = main['physical_compute_limit']
    budget = run = 0.0
    pairs = 0
    # Step 0 splits the initial stock itself, uncapped: D + R = D_init + R_init (the cap would differ by Q0/C_L = 5e-11).
    q0 = main['training_compute_init'] + main['runtime_compute_init']
    step0 = abs(t['training_compute'][0] + t['runtime_compute'][0] - q0) / q0
    for i in range(1, len(steps)):
        if steps[i] != steps[i - 1] + 1:
            continue
        pairs += 1
        g = usable(t['compute'][i - 1], c_l)
        budget = max(budget, abs(t['training_compute'][i] + t['runtime_compute'][i] - g) / g)
        d = t['training_compute'][i]
        run = max(run, abs(t['physical_best_training_run'][i] - t['physical_best_training_run'][i - 1] - d) / d)
    return {'step0_rel_err': step0, 'budget_max_rel_err': budget, 'training_run_max_rel_err': run, 'consecutive_pairs': pairs}


def build():
    target = json.loads(TARGET.read_text())
    jobs = {j['name']: j for j in target['jobs']}
    out = {
        'about': 'Generated by coupling_example.py from data/baseline_target.json (#13 pin). Issue #35. '
                 'Not a coupled run: AIFM is not rerun. H100e values are upper bounds (s = 1).',
        'bundle_sha256': target['bundle_sha256'],
        'flop_per_h100e_year': FLOP_PER_H100E_YEAR,
        'identities': {},
        'pass_upper_bound_h100e': {},
    }
    for name, job in jobs.items():
        if 'training_compute' in job['trajectory']:
            out['identities'][name] = {k: (float(f'{v:.3e}') if isinstance(v, float) else v)
                                       for k, v in split_identities(job).items()}
    for name in PRESETS:
        t, steps = jobs[name]['trajectory'], jobs[name]['steps']
        out['pass_upper_bound_h100e'][name] = {
            str(s): float(f'{t["training_compute"][steps.index(s)] / FLOP_PER_H100E_YEAR:.4e}') for s in REPORT_STEPS}
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--write', action='store_true')
    ap.add_argument('--check', action='store_true')
    a = ap.parse_args()
    out = build()
    text = json.dumps(out, indent=1, sort_keys=True) + '\n'
    if a.write:
        OUT.write_text(text)
    elif a.check:
        if OUT.read_text() != text:
            sys.exit(f'{OUT.name} is stale; rerun with --write and review the change')
    else:
        print(text, end='')


if __name__ == '__main__':
    main()
